/**
 * P2 agent names (src/schema/agents.ts): models come from config, GET /api/health lists the roster,
 * every model-call / chat / adversary / guard span carries `notary.agent`, and user-facing text
 * generated by core names the agents exactly (no stray lowercase role names, no "LLM").
 * Transports are TEST DOUBLES (no network).
 */
import { mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import type { ChatCompletion } from "openai/resources/chat/completions";
import { afterEach, describe, expect, it } from "vitest";
import { createHealth } from "../src/api/health.js";
import type { HealthProbes } from "../src/api/health.js";
import { LlmClient, agentModels, agentRoster } from "../src/llm/index.js";
import type { ChatTransport } from "../src/llm/index.js";
import { runLlmDoctor } from "../src/llm/doctor.js";
import { createGate } from "../src/queue/gate.js";
import { AGENTS, AGENT_ORDER } from "../src/schema/agents.js";
import { HealthResponseSchema } from "../src/schema/api.js";
import { ExplainFileSchema } from "../src/schema/explain.js";
import { TimelineFileSchema } from "../src/schema/timeline.js";
import type { QueueRequest } from "../src/schema/index.js";
import { setSpanSink } from "../src/trace/index.js";
import type { SpanRecord } from "../src/trace/index.js";

const ENV = {
  NOTARY_LLM_PROVIDER: "litellm",
  LITELLM_BASE_URL: "https://litellm.test.example/v1",
  LITELLM_API_KEY: ["fake", "agents", "key", "424242"].join("-"),
  NOTARY_MODEL_EXECUTOR: "test-haiku",
  NOTARY_MODEL_REFLECTOR: "test-sonnet",
  NOTARY_MODEL_ADVERSARY: "test-nova-pro",
};

const WEB_PUBLIC = fileURLToPath(new URL("../../web/public/", import.meta.url));

/** A lowercase role name standing alone (not inside an id like `fixture.adversary-double` or an env var), or "LLM". */
const STRAY = /(?<![\w.\-/`])(executor|reflector|adversary)(?![\w.\-/`])|\bLLM\b/;
/** Recorded text quoted from a bundle (belief event reasons, guard reasons) is data, not generated copy. */
const unquoted = (s: string): string => s.replace(/"[^"]*"/g, '""');

function completion(): ChatCompletion {
  return {
    id: "c",
    object: "chat.completion",
    created: 0,
    model: "m",
    choices: [{ index: 0, message: { role: "assistant", content: "OK", refusal: null }, finish_reason: "stop", logprobs: null }],
    usage: { prompt_tokens: 10, completion_tokens: 1, total_tokens: 11 },
  };
}
const okTransport: ChatTransport = async () => ({ completion: completion(), headers: {} });

const tmp: string[] = [];
afterEach(() => {
  setSpanSink(null);
  for (const d of tmp.splice(0)) rmSync(d, { recursive: true, force: true });
});

function spans(): { read: () => SpanRecord[] } {
  const dir = mkdtempSync(join(tmpdir(), "notary-agents-"));
  tmp.push(dir);
  const path = join(dir, "spans.jsonl");
  setSpanSink(path);
  return {
    read: () =>
      readFileSync(path, "utf8")
        .trim()
        .split("\n")
        .map((l) => JSON.parse(l) as SpanRecord),
  };
}

const noNetwork: HealthProbes = {
  listModels: async () => {
    throw new Error("no network in tests");
  },
  crustdata: async () => {
    throw new Error("no network in tests");
  },
  dodo: async () => {
    throw new Error("no network in tests");
  },
  entireOnPath: () => false,
  tracing: () => ({ init: null, lastFlush: null, exportedTraces: 0 }),
};

describe("agent models come from config", () => {
  it("one model id per model agent from NOTARY_MODEL_*; Notary Chat falls back to the reflector model", () => {
    expect(agentModels(ENV)).toEqual({ executor: "test-haiku", reflector: "test-sonnet", adversary: "test-nova-pro", chat: "test-sonnet" });
  });

  it("null when a variable is unset; a separation-of-duties breach still reports the configured ids (never throws)", () => {
    expect(agentModels({})).toEqual({ executor: null, reflector: null, adversary: null, chat: null });
    expect(agentModels({ NOTARY_MODEL_REFLECTOR: "same", NOTARY_MODEL_ADVERSARY: "same" })).toEqual({ executor: null, reflector: "same", adversary: "same", chat: "same" });
  });

  it("the roster is AGENTS in display order; the Guard is a rule with no model", () => {
    const roster = agentRoster(ENV);
    expect(roster.map((a) => a.id)).toEqual([...AGENT_ORDER]);
    for (const a of roster) expect(a).toMatchObject({ name: AGENTS[a.id].name, role: AGENTS[a.id].role, kind: AGENTS[a.id].kind });
    expect(roster.find((a) => a.id === "guard")).toMatchObject({ name: "Guard", kind: "rule", model: null });
  });
});

describe("GET /api/health agents", () => {
  it("lists every agent with the configured model", async () => {
    const res = HealthResponseSchema.parse(await createHealth({ env: ENV, probes: noNetwork }).check());
    expect(res.agents).toEqual([
      { id: "executor", name: "Executor", role: AGENTS.executor.role, kind: "model", model: "test-haiku" },
      { id: "reflector", name: "Reflector", role: AGENTS.reflector.role, kind: "model", model: "test-sonnet" },
      { id: "adversary", name: "Adversary", role: AGENTS.adversary.role, kind: "model", model: "test-nova-pro" },
      { id: "chat", name: "Notary Chat", role: AGENTS.chat.role, kind: "model", model: "test-sonnet" },
      { id: "guard", name: "Guard", role: AGENTS.guard.role, kind: "rule", model: null },
    ]);
    // The key is never in the response.
    expect(JSON.stringify(res)).not.toContain(ENV.LITELLM_API_KEY);
  });

  it("model is null for every agent when nothing is configured", async () => {
    const res = HealthResponseSchema.parse(await createHealth({ env: {}, probes: noNetwork }).check());
    expect(res.agents?.map((a) => [a.name, a.model])).toEqual([
      ["Executor", null],
      ["Reflector", null],
      ["Adversary", null],
      ["Notary Chat", null],
      ["Guard", null],
    ]);
  });
});

describe("notary.agent span attribute", () => {
  it("every notary.llm span names the agent: the role's owner by default, Notary Chat when it says so", async () => {
    const s = spans();
    const llm = new LlmClient({ env: ENV, chatTransport: okTransport });
    const msg = [{ role: "user" as const, content: "x" }];
    await llm.complete({ role: "executor", messages: msg });
    await llm.complete({ role: "reflector", messages: msg });
    await llm.complete({ role: "adversary", messages: msg });
    await llm.complete({ role: "executor", agent: "chat", messages: msg });
    const recs = s.read().filter((r) => r.name === "notary.llm");
    expect(recs.map((r) => [r.attrs["notary.agent"], r.attrs["notary.role"]])).toEqual([
      ["Executor", "executor"],
      ["Reflector", "reflector"],
      ["Adversary", "adversary"],
      ["Notary Chat", "executor"],
    ]);
    // Never a prompt in the attributes.
    for (const r of recs) expect(Object.values(r.attrs)).not.toContain("x");
  });

  it("each Guard verdict on a money action is one notary.guard GUARDRAIL span named Guard", async () => {
    const s = spans();
    const gate = createGate({ beliefs: () => [], probesForClaims: () => [] });
    const request = { id: "q-test", type: "refund", customerId: "cus_test", paymentId: "pay_test" } as unknown as QueueRequest;
    const v = await gate({ request, tier: "smb", policy: { outcome: "approve", action: "full_refund" } as never, forEscalation: true });
    expect(v.allow).toBe(false);
    const recs = s.read().filter((r) => r.name === "notary.guard");
    expect(recs).toHaveLength(1);
    expect(recs[0]).toMatchObject({ kind: "GUARDRAIL", status: "ok" });
    expect(recs[0]!.attrs).toMatchObject({
      "notary.agent": AGENTS.guard.name,
      "notary.requestId": "q-test",
      "notary.guard.action": "full_refund",
      "notary.guard.allow": false,
      "notary.guard.required": v.requiredBeliefs.length,
      "notary.guard.missing": v.missingBeliefs.length,
    });
  });
});

describe("generated user-facing text names the agents (no stray lowercase role names)", () => {
  const fixtureDir = join(WEB_PUBLIC, "bundles", "fixture");
  const timelines = readdirSync(fixtureDir)
    .filter((f) => f.endsWith(".timeline.json"))
    .map((f) => TimelineFileSchema.parse(JSON.parse(readFileSync(join(fixtureDir, f), "utf8"))));

  it("published fixture timeline summaries", () => {
    expect(timelines.length).toBeGreaterThan(0);
    const all = timelines.flatMap((t) => t.events.map((e) => e.summary));
    for (const s of all) expect(s, s).not.toMatch(STRAY);
    // The agents appear by name where they acted.
    expect(all.some((s) => s.startsWith(`${AGENTS.adversary.name} challenged `))).toBe(true);
    expect(all.some((s) => s.startsWith(`${AGENTS.reflector.name} proposed `))).toBe(true);
    expect(all.some((s) => s.startsWith(`${AGENTS.guard.name} held request `) && s.includes(" — no certificate for "))).toBe(true);
  });

  it("published explain answers (recorded quotes excluded)", () => {
    const file = ExplainFileSchema.parse(JSON.parse(readFileSync(join(WEB_PUBLIC, "content", "explain.json"), "utf8")));
    expect(file.answers.length).toBeGreaterThan(0);
    for (const a of file.answers) expect(unquoted(a.answer), a.id).not.toMatch(STRAY);
    expect(file.answers.some((a) => a.answer.includes(`${AGENTS.adversary.name} review: `))).toBe(true);
  });

  it("notary doctor --llm output", async () => {
    let t = 0;
    const good = await runLlmDoctor({ env: ENV, chatTransport: okTransport, listModels: async () => ["test-haiku", "test-sonnet", "test-nova-pro"], now: () => (t += 5) });
    const bad = await runLlmDoctor({ env: { ...ENV, NOTARY_MODEL_ADVERSARY: "test-sonnet", NOTARY_MODEL_EXECUTOR: "" }, chatTransport: okTransport, listModels: async () => ["test-sonnet"] });
    const lines = [...good.lines, ...bad.lines];
    for (const l of lines) expect(l, l).not.toMatch(STRAY);
    for (const a of ["executor", "reflector", "adversary"] as const) expect(good.lines.join("\n")).toContain(`${AGENTS[a].name} (NOTARY_MODEL_${a.toUpperCase()}) = `);
  });
});
